update lanchas set dados='{"pes": 35, "capacidade": 16, "cidade": "buzios", "frase": {"pt": "Totalmente reformada, climatizada e com som premium. Ideal para família, amigos e comemorações.", "en": "Fully refurbished, air-conditioned and with a premium sound system. Ideal for families, friends and celebrations.", "es": "Totalmente reformada, climatizada y con sonido premium. Ideal para familias, amigos y celebraciones."}, "descricao": {"pt": "A Miss Bardot é o cenário perfeito para viver o melhor de Búzios: passeio romântico, momento em família ou um dia entre amigos. São 35 pés com ambientes climatizados, cabine com cama de casal e TV, banheiro, cozinha com air fryer e churrasqueira. O grande destaque é o sistema de som premium Hertz Marine: áudio potente e cristalino, feito para tocar alto ao ar livre sem perder a qualidade. É só conectar a sua playlist por Bluetooth e transformar o mar de Búzios na sua pista de dança. Passeios de dia, pôr do sol ou, sob consulta, noturnos.", "en": "Miss Bardot is the perfect setting to enjoy the best of Búzios: a romantic outing, family time or a day with friends. 35 feet with air-conditioned spaces, a cabin with a double bed and TV, a bathroom, and a galley with an air fryer and barbecue grill. The highlight is the premium Hertz Marine sound system: powerful, crystal-clear audio made to play loud in the open air without losing quality. Just connect your playlist via Bluetooth and turn the Búzios sea into your dance floor. Day and sunset tours, and night tours on request.", "es": "La Miss Bardot es el escenario perfecto para vivir lo mejor de Búzios: un paseo romántico, un momento en familia o un día entre amigos. Son 35 pies con ambientes climatizados, camarote con cama doble y TV, baño, cocina con freidora de aire y parrilla. Lo más destacado es el sistema de sonido premium Hertz Marine: audio potente y nítido, hecho para sonar fuerte al aire libre sin perder calidad. Solo tienes que conectar tu playlist por Bluetooth y convertir el mar de Búzios en tu pista de baile. Paseos de día, al atardecer o, a consultar, nocturnos."}, "embarque": {"4": ["Porto Veleiro (Praia dos Ossos)"], "7": ["Porto Veleiro (Praia dos Ossos)", "BR Marina"]}}'::jsonb, atualizado_em=now() where slug='miss-bardot' and dados is null;
update lanchas set dados='{"pes": 26, "capacidade": 8, "cidade": "buzios", "frase": {"pt": "Lancha de 26 pés com toldo, solário na popa e banheiro. Ideal para casais, famílias e grupos pequenos.", "en": "A 26-foot boat with a canopy, stern sun deck and bathroom. Ideal for couples, families and small groups.", "es": "Lancha de 26 pies con toldo, solárium en la popa y baño. Ideal para parejas, familias y grupos pequeños."}, "descricao": {"pt": "A Les Zuzu é uma lancha de 26 pés para até 8 pessoas, perfeita para casais, famílias e grupos pequenos curtirem as praias de Búzios com mais privacidade. Tem toldo para sombra e solário na popa para tomar sol entre um mergulho e outro.", "en": "Les Zuzu is a 26-foot boat for up to 8 people, perfect for couples, families and small groups to enjoy the beaches of Búzios with more privacy. It has a canopy for shade and a sun pad at the stern for sunbathing between swims.", "es": "La Les Zuzu es una lancha de 26 pies para hasta 8 personas, perfecta para que parejas, familias y grupos pequeños disfruten las playas de Búzios con más privacidad. Tiene toldo para dar sombra y solárium en la popa para tomar sol entre un chapuzón y otro."}, "embarque": {"4": ["Porto Veleiro (Praia dos Ossos)"], "7": ["Porto Veleiro (Praia dos Ossos)", "BR Marina"]}}'::jsonb, atualizado_em=now() where slug='les-zuzu' and dados is null;
update lanchas set dados='{"pes": 32, "capacidade": 12, "cidade": "buzios", "frase": {"pt": "Lancha de 32 pés com piscina inflável, banheiro e som Bluetooth. Ideal para famílias e grupos de amigos.", "en": "A 32-foot boat with an inflatable pool, bathroom and Bluetooth sound. Ideal for families and groups of friends.", "es": "Lancha de 32 pies con piscina inflable, baño y sonido Bluetooth. Ideal para familias y grupos de amigos."}, "descricao": {"pt": "A Midas é uma lancha de 32 pés para até 12 pessoas, ótima para grupos médios curtirem as praias de Búzios com conforto. Tem banheiro a bordo e piscina inflável para aproveitar o mar.", "en": "Midas is a 32-foot boat for up to 12 people, great for mid-sized groups to enjoy the beaches of Búzios in comfort. It has a bathroom on board and an inflatable pool to make the most of the sea.", "es": "La Midas es una lancha de 32 pies para hasta 12 personas, ideal para que grupos medianos disfruten las playas de Búzios con comodidad. Tiene baño a bordo y piscina inflable para aprovechar el mar."}, "embarque": {"4": ["Píer do Golfinho (Praia dos Ossos)"], "7": ["Píer do Golfinho (Praia dos Ossos)"]}}'::jsonb, atualizado_em=now() where slug='midas' and dados is null;
update lanchas set dados='{"pes": 22, "capacidade": 6, "cidade": "buzios", "frase": {"pt": "Lancha de 22 pés com banheiro, tapete flutuante e som Bluetooth. Ideal para casais e grupos pequenos.", "en": "A 22-foot boat with a bathroom, floating mat and Bluetooth sound. Ideal for couples and small groups.", "es": "Lancha de 22 pies con baño, alfombra flotante y sonido Bluetooth. Ideal para parejas y grupos pequeños."}, "descricao": {"pt": "A Compostela é uma lancha de 22 pés para até 6 pessoas, perfeita para casais, famílias e grupos pequenos curtirem as praias de Búzios com privacidade. Tem toldo para sombra, solário na proa e cabine com banheiro.", "en": "Compostela is a 22-foot boat for up to 6 people, perfect for couples, families and small groups to enjoy the beaches of Búzios in privacy. It has a canopy for shade, a sun pad on the bow and a cabin with a bathroom.", "es": "La Compostela es una lancha de 22 pies para hasta 6 personas, perfecta para que parejas, familias y grupos pequeños disfruten las playas de Búzios con privacidad. Tiene toldo para dar sombra, solárium en la proa y camarote con baño."}, "embarque": {"4": ["Píer do Golfinho (Praia dos Ossos)"], "7": ["Píer do Golfinho (Praia dos Ossos)"]}}'::jsonb, atualizado_em=now() where slug='compostela' and dados is null;
update lanchas set dados='{"pes": 26, "capacidade": 11, "cidade": "buzios", "frase": {"pt": "Lancha de 26 pés com banheiro, piscina inflável e sofá em U na popa. Ideal para famílias e amigos.", "en": "A 26-foot boat with a bathroom, inflatable pool and U-shaped sofa at the stern. Ideal for families and friends.", "es": "Lancha de 26 pies con baño, piscina inflable y sofá en U en la popa. Ideal para familias y amigos."}, "descricao": {"pt": "A Bubbles é uma lancha de 26 pés para até 11 pessoas, ótima para famílias e grupos de amigos curtirem as praias de Búzios com conforto. Tem toldo para sombra, sofá em U na popa com mesa, estofados na proa e banheiro a bordo.", "en": "Bubbles is a 26-foot boat for up to 11 people, great for families and groups of friends to enjoy the beaches of Búzios in comfort. It has a canopy for shade, a U-shaped sofa with a table at the stern, padded seating on the bow and a bathroom on board.", "es": "La Bubbles es una lancha de 26 pies para hasta 11 personas, ideal para que familias y grupos de amigos disfruten las playas de Búzios con comodidad. Tiene toldo para dar sombra, sofá en U con mesa en la popa, colchonetas en la proa y baño a bordo."}, "embarque": {"4": ["Píer do Golfinho (Praia dos Ossos)"], "7": ["Píer do Golfinho (Praia dos Ossos)"]}}'::jsonb, atualizado_em=now() where slug='bubbles' and dados is null;